mapper.update:
UPDATE following
SET type = #{type}, update_time = NOW(3)
WHERE from_user_id = #{fromUserId} AND to_user_id = #{toUserId}

UPDATE follower
SET type = #{type}, update_time = NOW(3)
WHERE from_user_id = #{fromUserId} AND to_user_id = #{toUserId}

mapper.select:
SELECT id, from_user_id AS fromUserId, to_user_id AS toUserId,
       type, create_time AS createTime, update_time AS updateTime
FROM following
WHERE from_user_id = #{fromUserId} AND type = #{type}
ORDER BY update_time DESC
LIMIT #{limit}

SELECT id, from_user_id AS fromUserId, to_user_id AS toUserId,
       type, create_time AS createTime, update_time AS updateTime
FROM follower
WHERE to_user_id = #{toUserId} AND type = #{type}
ORDER BY update_time DESC
LIMIT #{limit}
